export function emperorsBladeNative(r,n){
 const t=r?.talents?.bb??{},s=STATS[r?.level];
 if(!isEmperorsBlade(r)||!s||r.stats.maxHp!==s.maxHp||r.stats.atk!==s.atk||r.applyWay!=="ALL"||r.stats.dmgType!=="phys"||r.stats.motion!=="WALK"
  ||r.stats.rangeRadius!==2||r.stats.blockCnt!==1||r.sp||r.notCountInTotal||!same(r.abilities,EMPERORS_BLADE_ABILITIES)
  ||!same(r.talents.groups,GROUPS)||!RATIOS.every(k=>ratio(t[k]))||!same(Object.fromEntries(Object.entries(t).filter(([k])=>!RATIOS.includes(k))),TALENTS)||!same(r.talents.bbStr,{})||!same(r.skills,SKILLS))return false;
 if(!same(closure(n),COMPONENTS)||Object.entries(TEMPLATES).some(([k,v])=>!same(n.$template(k),v))
  ||Object.entries(PROJECTILES).some(([k,v])=>!same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v))
  ||Object.entries(RANGES).some(([k,v])=>!same(n.$range(k),v)))return false;
 const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator),clock=clocks.enemies[r.prefabKey];
 const clip=(key,name)=>graphic?._animations.some(a=>a.animKey===key&&a.animName===name&&a.speed===1&&!a.loop);
 return !!clock&&n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID===clock.source?.skeletonDataPathId
  &&clip("Attack_1","Attack01")&&clip("Attack_2","Attack02")&&clip("Skill_1","Skill_01")&&clip("Skill_2_Begin","Skill_02_Begin")&&clip("Skill_2_End","Skill_02_End")
  &&Object.entries(CLOCK.durations).every(([k,v])=>clock.durations[k]===v)
  &&Object.entries(CLOCK.events).every(([k,v])=>clock.events[k]?.length===1&&clock.events[k][0].name==="OnAttack"&&clock.events[k][0].time===v);
}
/**
 * Runtime parameters. Talent and skill values come from the record; the rest from the pinned components:
 * the Dominion projectiles' 1.45 s delay, the 0.3 s pulse and its 0.6 s
 * buff, the `x-1` Dominion range, and the clip clocks (Attack01 for the ranged attack stand, Skill_01 for
 * Collapsing Fear, Skill_02_Begin's strike for the revive's field-wide cast).
 */
export function emperorsBladeParams(r){
 const t=r.talents.bb,skill=k=>r.skills.find(s=>s.prefabKey===k);
 const form=(ratio,k,radius)=>({hpRatio:t[ratio],radius,scale:skill(k).bb.atk_scale,cooldown:skill(k).cooldown,initial:skill(k).initCooldown});
 return {
  form1:form("BlackFogTriggerP1.hp_ratio","BlackRingP1",2),form2:form("BlackFogTriggerP2.hp_ratio","BlackRingP2",2.5),
  rebirth:t["Reborn.duration"],// Full HP: the owner checked in game (2026-11-17); the pinned _hpRechargeRatio 0.5 does not set it.
  rebornHp:1,invincible:t["Reborn.reborn_invincible.duration"],rebornAtk:t["Reborn.atk"],
  ringScale:t["Reborn.atk_scale"],ringRelease:CLOCK.events.Skill_02_Begin,combatScale:t["Combat.attack@combat_atkscale.atk_scale"],
  fogAspd:t["BlackFog.attack_speed"],fogResistance:t["BlackFog.damage_resistance"],aoeRadius:t["BlackFog.range_radius"],aoeScale:1,
  fogDelay:f32(1.45),fogInterval:f32(.3),fogBuffDuration:f32(.6),fogRange:RANGES["x-1"].grids,
  fearRelease:CLOCK.events.Skill_01,fearDuration:CLOCK.durations.Skill_01,
  attackAnim:{dur:CLOCK.durations.Attack01,hit:CLOCK.events.Attack01},
 };
}
